using CosmicBlock.UI;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
public static class HomeMenuMeshBuilder {
 public static void Run(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");var flow=Object.FindAnyObjectByType<GameFlowController>();var home=flow.HomeRoot.transform;var medium=Font("Medium");var semi=Font("SemiBold");var play=home.Find("MainActions/GameStartButton");var collection=home.Find("MainActions/PlanetCollectionButton");var settings=home.Find("BottomActions/SettingsButton");var quit=home.Find("BottomActions/QuitButton");
  ButtonFace(play,new Color(.04f,.08f,.18f,.88f),new Color(.92f,.76f,.40f,.95f));ButtonFace(collection,new Color(.035f,.075f,.18f,.88f),new Color(.30f,.77f,.96f,.90f));ButtonFace(settings,new Color(.06f,.095f,.20f,.90f),new Color(.29f,.52f,.77f,.75f));ButtonFace(quit,new Color(.06f,.095f,.20f,.90f),new Color(.29f,.52f,.77f,.75f));
  var p=Label(play,"MeshPrimaryLabel","게임 시작",semi,new Color(1,.94f,.78f));Place(p.rectTransform,.23f,.1f,.83f,.9f);Icon(play,"MeshIcon",HomeMenuIcon.Play,new Color(1,.85f,.53f),.10f,.28f,.20f,.72f);
  var c=Label(collection,"MeshCollectionLabel","행성 도감",semi,new Color(.81f,.94f,1));Place(c.rectTransform,.22f,.1f,.80f,.9f);Icon(collection,"MeshIcon",HomeMenuIcon.Orbit,new Color(.65f,.90f,1),.09f,.23f,.21f,.77f);Icon(collection,"MeshChevron",HomeMenuIcon.Chevron,new Color(.8f,.96f,1),.85f,.30f,.92f,.70f);
  foreach(var pair in new[]{settings,quit}){var oldIcon=pair.Find("Icon");if(oldIcon!=null)oldIcon.gameObject.SetActive(false);var oldLabel=pair.Find("Label");if(oldLabel!=null)oldLabel.gameObject.SetActive(false);var label=Label(pair,"MeshUtilityLabel",pair==settings?"설정":"게임 종료",semi,new Color(.85f,.92f,1));Place(label.rectTransform,.26f,.1f,.96f,.9f);Icon(pair,"MeshIcon",pair==settings?HomeMenuIcon.Settings:HomeMenuIcon.Power,new Color(.64f,.84f,1),.08f,.22f,.24f,.78f);}
  var frame=home.Find("BestScoreArea/Frame");Transparent(frame);Surface(frame,new Color(.035f,.07f,.16f,.78f),new Color(.34f,.57f,.76f,.65f),false);var old=frame.Find("ScoreValueArea");old.gameObject.SetActive(false);var name=Label(frame,"MeshBestLabel","최고 점수",medium,new Color(.90f,.94f,1));Place(name.rectTransform,.16f,.1f,.50f,.9f);name.alignment=TextAlignmentOptions.Left;var value=Label(frame,"MeshBestValue","0",semi,new Color(1,.90f,.69f));Place(value.rectTransform,.52f,.1f,.94f,.9f);value.alignment=TextAlignmentOptions.Right;value.enableAutoSizing=true;value.fontSizeMin=16;value.fontSizeMax=34;Icon(frame,"MeshIcon",HomeMenuIcon.Trophy,new Color(1,.84f,.50f),.04f,.22f,.13f,.78f);
  var newGame=home.Find("NewGameButton");Transparent(newGame);foreach(var legacy in newGame.GetComponentsInChildren<Text>(true))legacy.gameObject.SetActive(false);var newText=Label(newGame,"MeshNewLabel","새 게임 시작",medium,new Color(.82f,.89f,.98f));Place(newText.rectTransform,0,0,1,1);var newFace=Surface(newGame,new Color(.035f,.065f,.14f,.85f),new Color(.32f,.50f,.69f,.25f),false);Place(newFace.rectTransform,.15f,0,.85f,1);newFace.Style(new Color(.035f,.065f,.14f,.85f),new Color(.32f,.50f,.69f,.25f),12,.5f);newGame.GetComponent<Button>().targetGraphic=newGame.GetComponent<Image>();newGame.GetComponent<Image>().raycastTarget=true;
  home.GetComponent<HomeRunControls>().ConfigureMeshLabel(p);var layout=home.GetComponent<HomeMenuMeshLayout>()??home.gameObject.AddComponent<HomeMenuMeshLayout>();layout.Configure(value);home.GetComponent<HomeFinalLayout>().Apply();EditorUtility.SetDirty(home.GetComponent<HomeRunControls>());EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("HOME_MENU_MESH_READY");EditorApplication.Exit(0);
 }
 static TMP_FontAsset Font(string weight){var f=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Fonts/CosmicPopup"+weight+".asset");f.atlasPopulationMode=AtlasPopulationMode.Dynamic;f.ClearFontAssetData();string chars="게임을 종료할까요?현재 게임은 저장되어 다음에 이어서 플레이할 수 있어요.취소종료홈으로 돌아갈까요?진행 중인 게임은 저장돼요.홈에서 이어서 플레이할 수 있어요.계속하기설정배경음악효과음음악 볼륨진동닫기ONOFF0123456789%,.이어하기게임 시작행성 도감최고 점수새 게임 시작";if(!f.TryAddCharacters(chars+CollectionMeshBuilder.Characters))throw new System.Exception("HOME glyph missing "+weight);f.atlasPopulationMode=AtlasPopulationMode.Static;EditorUtility.SetDirty(f);foreach(var a in f.atlasTextures)EditorUtility.SetDirty(a);return f;}
 static void Transparent(Transform t){var image=t.GetComponent<Image>();if(image!=null){image.color=Color.clear;image.raycastTarget=false;}foreach(var shadow in t.GetComponents<Shadow>())Object.DestroyImmediate(shadow);}
 static void ButtonFace(Transform t,Color fill,Color edge){Transparent(t);t.GetComponent<Button>().targetGraphic=Surface(t,fill,edge,true);}
 static HomeQuitMeshGraphic Surface(Transform parent,Color fill,Color edge,bool hit){var r=Node(parent,"MeshSurface");r.SetAsFirstSibling();Place(r,0,0,1,1);var g=r.GetComponent<HomeQuitMeshGraphic>()??r.gameObject.AddComponent<HomeQuitMeshGraphic>();g.Style(fill,edge,24,1.8f);g.color=Color.white;g.raycastTarget=hit;return g;}
 static TextMeshProUGUI Label(Transform parent,string name,string value,TMP_FontAsset font,Color color){var r=Node(parent,name);var t=r.GetComponent<TextMeshProUGUI>()??r.gameObject.AddComponent<TextMeshProUGUI>();t.font=font;t.text=value;t.color=color;t.alignment=TextAlignmentOptions.Center;t.fontStyle=FontStyles.Normal;t.fontSize=32;t.enableAutoSizing=false;t.raycastTarget=false;return t;}
 static void Icon(Transform parent,string name,HomeMenuIcon value,Color color,float x0,float y0,float x1,float y1){var r=Node(parent,name);Place(r,x0,y0,x1,y1);var g=r.GetComponent<HomeMenuIconGraphic>()??r.gameObject.AddComponent<HomeMenuIconGraphic>();g.Configure(value);g.color=color;}
 static RectTransform Node(Transform parent,string name){var old=parent.Find(name);if(old!=null)return (RectTransform)old;var go=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer));go.transform.SetParent(parent,false);return (RectTransform)go.transform;}
 static void Place(RectTransform r,float x0,float y0,float x1,float y1){r.anchorMin=new Vector2(x0,y0);r.anchorMax=new Vector2(x1,y1);r.offsetMin=r.offsetMax=Vector2.zero;}
}
